def _recover_one(transaction_dir: Path, recovery_root: Path, allowed_targets: set[Path] | None = None) -> None:
    journal_path = transaction_dir / "journal.json"
    if not journal_path.exists():
        # Replacement never starts before the first journal is durable.
        _cleanup_transaction(transaction_dir)
        return
    journal = _read_journal(journal_path)
    entries = journal["entries"]
    checked: list[tuple[dict[str, Any], Path, str | None]] = []
    for index, raw in enumerate(entries):
        if not isinstance(raw, dict):
            raise DocumentTransactionError(
                "document_transaction_journal_invalid",
                f"事务日志 entries[{index}] 无效",
            )
        raw_target = raw.get("target")
        if not isinstance(raw_target, str) or not Path(raw_target).is_absolute():
            raise DocumentTransactionError("document_transaction_journal_invalid", "事务日志缺少明确目标路径")
        target = Path(raw_target)
        target = _scoped_target(target, recovery_root, allowed_targets)
        original = raw.get("original_sha256")
        replacement = raw.get("replacement_sha256")
        if (
            original is not None
            and (
                not isinstance(original, str)
                or len(original) != 64
            )
        ) or not isinstance(replacement, str) or len(replacement) != 64:
            raise DocumentTransactionError(
                "document_transaction_journal_invalid",
                f"事务日志 entries[{index}] 摘要无效",
            )
        current = _current_digest(target)
        checked.append((raw, target, current))

    if journal["state"] == "committed":
        conflicts = [
            str(target)
            for raw, target, current in checked
            if current != raw["replacement_sha256"]
        ]
        if conflicts:
            raise DocumentTransactionError(
                "document_transaction_recovery_conflict",
                "已提交事务的目标字节发生变化，拒绝猜测恢复",
                details=conflicts,
            )
        _cleanup_transaction(transaction_dir)
        return

    conflicts = [
        str(target)
        for raw, target, current in checked
        if current
        not in {raw.get("original_sha256"), raw["replacement_sha256"]}
    ]
    if conflicts:
        raise DocumentTransactionError(
            "document_transaction_recovery_conflict",
            "未提交事务之后出现第三方文件变化，拒绝覆盖",
            details=conflicts,
        )

    restored: list[str] = []
    try:
        for index, (raw, target, _current) in enumerate(reversed(checked)):
            original = raw.get("original_sha256")
            live = _current_digest(target)
            if live == original:
                continue
            if live != raw["replacement_sha256"]:
                raise DocumentTransactionError("document_transaction_recovery_conflict", "恢复期间目标出现第三方变化", details={"target": str(target)})
            if original is None:
                target.unlink(missing_ok=True)
                _fsync_directory(target.parent)
                restored.append(str(target))
                continue
            backup = _journal_path(
                recovery_root,
                raw.get("backup"),
                f"entries[{len(checked) - index - 1}].backup",
            )
            if not backup.is_file() or _sha256(backup.read_bytes()) != original:
                raise DocumentTransactionError(
                    "document_transaction_backup_invalid",
                    f"事务旧文件副本无效：{backup}",
                )
            target.parent.mkdir(parents=True, exist_ok=True)
            _replace_file(backup, target)
            mode = raw.get("original_mode")
            if type(mode) is int:
                os.chmod(target, mode)
            _fsync_directory(target.parent)
            restored.append(str(target))
    except (OSError, DocumentTransactionError) as error:
        raise DocumentTransactionError(
            "document_transaction_rollback_incomplete",
            "文档事务恢复未能完整回滚",
            details={"restored": restored, "error": str(error)},
        ) from error
    _cleanup_transaction(transaction_dir)


def recover_document_transactions(
    transaction_root: Path,
    recovery_root: Path,
    *, allowed_targets: Sequence[Path] | None = None,
) -> int:
    """Recover every durable transaction journal under one exact root."""

    root = recovery_root.resolve()
    for directory in (transaction_root.absolute(), *transaction_root.absolute().parents):
        if directory.is_symlink() or directory.is_junction():
            raise DocumentTransactionError("document_transaction_path_invalid", "事务目录不得经过链接或联接点")
    transactions = transaction_root.resolve(strict=False)
    if not transactions.is_relative_to(root):
        raise DocumentTransactionError(
            "document_transaction_path_invalid",
            "事务目录必须位于恢复根目录内",
        )
    if not transactions.exists():
        return 0
    if not transactions.is_dir() or transactions.is_symlink():
        raise DocumentTransactionError(
            "document_transaction_path_invalid",
            "事务根目录不是普通目录",
        )
    recovered = 0
    for candidate in sorted(transactions.iterdir()):
        if not candidate.name.startswith("txn-"):
            continue
        if not candidate.is_dir() or candidate.is_symlink():
            raise DocumentTransactionError(
                "document_transaction_path_invalid",
                f"事务条目不是普通目录：{candidate}",
            )
        _recover_one(candidate, root, {path.resolve(strict=False) for path in allowed_targets} if allowed_targets is not None else None)
        recovered += 1
    return recovered


def replace_documents(
    documents: Sequence[tuple[Path, bytes]],
    *,
    validate_replaced: Callable[[], None] | None = None,
    transaction_root: Path | None = None,
    recovery_root: Path | None = None,
    expected_originals: Mapping[Path, str | None] | None = None,
    allowed_targets: Sequence[Path] | None = None,
) -> None:
    """Replace all documents with a durable journal and crash recovery."""

    if not documents:
        raise ValueError("documents must not be empty")
    targets = [target.absolute() for target, _content in documents]
    if len(set(targets)) != len(targets):
        raise ValueError("document transaction targets must be unique")
    if recovery_root is None and len({path.parent for path in targets}) > 1:
        raise DocumentTransactionError("document_transaction_recovery_root_required", "分离位置的文档事务必须给出明确恢复根目录和目标清单")
    root = (
        recovery_root.resolve()
        if recovery_root is not None
        else Path(os.path.commonpath([str(path.parent) for path in targets])).resolve()
    )
    transactions = (
        transaction_root.resolve(strict=False)
        if transaction_root is not None
        else root / ".strixnova" / "artifacts" / "document-transactions"
    )
    if not transactions.is_relative_to(root):
        raise DocumentTransactionError(
            "document_transaction_path_invalid",
            "事务目录必须位于恢复根目录内",
        )
    permitted = {path.resolve(strict=False) for path in allowed_targets} if allowed_targets is not None else None
    targets = [_scoped_target(target, root, permitted) for target in targets]
    transactions.mkdir(parents=True, exist_ok=True)
    recover_document_transactions(transactions, root, allowed_targets=allowed_targets)

    transaction_dir = transactions / f"txn-{uuid.uuid4().hex}"
    transaction_dir.mkdir()
    _fsync_directory(transactions)
    entries: list[dict[str, Any]] = []
    try:
        for index, ((target, content), resolved_target) in enumerate(
            zip(documents, targets, strict=True)
        ):
            if not isinstance(content, bytes):
                raise TypeError("document transaction content must be bytes")
            if resolved_target.exists() and not resolved_target.is_file():
                raise DocumentTransactionError(
                    "document_transaction_path_invalid",
                    f"事务目标不是普通文件：{resolved_target}",
                )
            original = (
                resolved_target.read_bytes()
                if resolved_target.exists()
                else None
            )
            if expected_originals is not None and (
                resolved_target not in expected_originals
                or (_sha256(original) if original is not None else None) != expected_originals[resolved_target]
            ):
                raise DocumentTransactionError("document_transaction_recovery_conflict", f"事务目标已不等于预检内容：{resolved_target}")
            mode = (
                resolved_target.stat().st_mode
                if resolved_target.exists()
                else None
            )
            backup = transaction_dir / f"backup-{index:04d}.bin"
            if original is not None:
                _write_bytes(backup, original)
            replacement = transaction_dir / f"replacement-{index:04d}.bin"
            _write_bytes(replacement, content)
            if mode is not None:
                os.chmod(replacement, mode)
            entries.append(
                {
                    "target": str(resolved_target),
                    "backup": (
                        _relative_path(root, backup, "backup")
                        if original is not None
                        else None
                    ),
                    "replacement": _relative_path(
                        root,
                        replacement,
                        "replacement",
                    ),
                    "original_sha256": (
                        _sha256(original) if original is not None else None
                    ),
                    "replacement_sha256": _sha256(content),
                    "original_mode": mode,
                }
            )
        _fsync_directory(transaction_dir)
        journal = {
            "schema_version": TRANSACTION_SCHEMA,
            "transaction_id": transaction_dir.name,
            "state": "prepared",
            "replaced_count": 0,
            "entries": entries,
        }
        journal_path = transaction_dir / "journal.json"
        _write_journal(journal_path, journal)
        journal["state"] = "replacing"
        _write_journal(journal_path, journal)
        for index, (raw, target) in enumerate(zip(entries, targets, strict=True)):
            if _current_digest(target) != raw["original_sha256"]:
                raise DocumentTransactionError("document_transaction_recovery_conflict", f"替换前目标内容已改变：{target}")
            replacement = _journal_path(
                root,
                raw["replacement"],
                f"entries[{index}].replacement",
            )
            target.parent.mkdir(parents=True, exist_ok=True)
            _replace_file(replacement, target)
            _fsync_directory(target.parent)
            journal["replaced_count"] = index + 1
            _write_journal(journal_path, journal)
        journal["state"] = "validating"
        _write_journal(journal_path, journal)
        if validate_replaced is not None:
            validate_replaced()
        journal["state"] = "committed"
        _write_journal(journal_path, journal)
    except BaseException:
        # In-process failures take the same durable recovery path.  A hard
        # process termination skips this block and is recovered next entry.
        try:
            if transaction_dir.exists():
                _recover_one(transaction_dir, root, permitted)
        except DocumentTransactionError:
            raise
        raise
    _recover_one(transaction_dir, root, permitted)

def render_yaml_value_patches(
    original: bytes,
    replacements: Mapping[tuple[str | int, ...], Any],
) -> bytes:
    """Return exact YAML bytes with only the selected value nodes replaced."""

    has_bom = original.startswith(b"\xef\xbb\xbf")
    try:
        text = original.decode("utf-8-sig")
    except UnicodeDecodeError as error:
        raise YamlMetadataPatchError("YAML 内容必须是 UTF-8") from error
    try:
        root = yaml.compose(text)
    except yaml.YAMLError as error:
        raise YamlMetadataPatchError("YAML 内容无法解析") from error
    if root is None:
        raise YamlMetadataPatchError("YAML 内容不能为空")

    spans: list[tuple[int, int, str]] = []
    for raw_path, value in replacements.items():
        metadata_path = tuple(raw_path)
        if not metadata_path:
            raise YamlMetadataPatchError("YAML 元数据路径不能为空")
        node, key_end = _node_at(root, metadata_path)
        start = node.start_mark.index
        end = node.end_mark.index
        same_line_prefix = ""
        if key_end is not None and "\n" in text[key_end:start]:
            colon = text.find(":", key_end, start)
            if colon < 0:
                raise YamlMetadataPatchError(
                    "YAML 元数据映射缺少分隔符：" + ".".join(map(str, metadata_path))
                )
            start = colon + 1
            same_line_prefix = " "
        original_span = text[start:end]
        trailing = re.search(r"(\r?\n[ \t]*)$", original_span)
        replacement = same_line_prefix + _yaml_inline(value)
        if trailing is not None:
            replacement += trailing.group(1)
        spans.append((start, end, replacement))
    spans.sort(reverse=True)
    previous_start = len(text) + 1
    updated = text
    for start, end, replacement in spans:
        if end > previous_start:
            raise YamlMetadataPatchError("YAML 元数据替换范围发生重叠")
        updated = updated[:start] + replacement + updated[end:]
        previous_start = start
    try:
        yaml.safe_load(updated)
    except yaml.YAMLError as error:
        raise YamlMetadataPatchError("YAML 元数据替换后无法回读") from error
    encoded = updated.encode("utf-8")
    if has_bom:
        encoded = b"\xef\xbb\xbf" + encoded
    return encoded


def _transaction_target(project: Path, relative_path: str) -> Path:
    try:
        normalized = repository_relative_path(
            relative_path,
            "YAML 事务路径",
        )
    except GitProjectReaderError as error:
        raise YamlMetadataPatchError(
            str(error),
            code="yaml_transaction_path_unsafe",
            details=error.details,
        ) from error
    for ancestor in (project.absolute(), *project.absolute().parents):
        if ancestor.is_symlink() or ancestor.is_junction():
            raise YamlMetadataPatchError("YAML 事务根目录不得经过链接", code="yaml_transaction_path_unsafe")
    project = project.resolve()
    candidate = project
    for part in normalized.split("/"):
        candidate = candidate / part
        if candidate.is_symlink() or candidate.is_junction():
            raise YamlMetadataPatchError(
                f"YAML 事务路径不得经过符号链接：{normalized}",
                code="yaml_transaction_path_unsafe",
                details={"path": normalized},
            )
    try:
        target = candidate.resolve()
        target.relative_to(project)
    except (OSError, RuntimeError, ValueError) as error:
        raise YamlMetadataPatchError(
            "YAML 事务路径不得离开项目目录",
            code="yaml_transaction_path_unsafe",
        ) from error
    return target


def build_yaml_patch_transaction(
    project_dir: str | Path,
    updates: Mapping[str | tuple[str | None, str], Mapping[tuple[str | int, ...], Any]],
    *, repository_roots: Mapping[str | None, str | Path] | None = None,
) -> dict[str, Any]:
    """Freeze deterministic metadata edits before any file is changed.

    The durable record contains only repository-relative paths, exact before
    and after hashes, and narrow scalar replacements.  It never stores whole
    authority documents in workflow state.
    """

    project = Path(project_dir).resolve()
    roots = {identifier: Path(root).absolute() for identifier, root in (repository_roots or {None: project}).items()}
    entries: list[dict[str, Any]] = []
    seen_targets: set[str] = set()
    for key in sorted(updates, key=str):
        identifier, relative_path = key if isinstance(key, tuple) else (None, key)
        if identifier not in roots:
            raise YamlMetadataPatchError("YAML 事务目标仓库没有明确绑定", code="yaml_transaction_repository_missing")
        target = _transaction_target(roots[identifier], relative_path)
        target_identity = os.path.normcase(str(target))
        if target_identity in seen_targets:
            raise YamlMetadataPatchError(
                "YAML 元数据事务文件路径指向同一目标",
                code="yaml_transaction_path_duplicate",
            )
        seen_targets.add(target_identity)
        try:
            original = target.read_bytes()
        except OSError as error:
            raise YamlMetadataPatchError(
                f"无法读取 YAML 事务文件：{relative_path}"
            ) from error
        replacements = updates[key]
        updated = render_yaml_value_patches(original, replacements)
        serialized = [
            {"path": list(metadata_path), "value": value}
            for metadata_path, value in sorted(
                replacements.items(),
                key=lambda item: tuple(str(part) for part in item[0]),
            )
        ]
        entries.append(
            {
                "path": relative_path,
                "repository_id": identifier,
                "root_path": str(roots[identifier].resolve()),
                "before_sha256": hashlib.sha256(original).hexdigest(),
                "after_sha256": hashlib.sha256(updated).hexdigest(),
                "replacements": serialized,
            }
        )
    return {
        "schema_version": YAML_PATCH_TRANSACTION_SCHEMA,
        "entries": entries,
    }


def apply_yaml_patch_transaction(
    project_dir: str | Path,
    transaction: Mapping[str, Any],
    *, repository_roots: Mapping[str | None, str | Path] | None = None,
) -> dict[Path, bytes]:
    """Idempotently finish a previously frozen metadata transaction.

    Every file must still be either the exact pre-write body or the exact
    intended post-write body.  This permits restart recovery after any atomic
    per-file replacement while refusing unrelated edits.
    """

    if transaction.get("schema_version") != YAML_PATCH_TRANSACTION_SCHEMA:
        raise YamlMetadataPatchError("YAML 元数据事务版本无效")
    raw_entries = transaction.get("entries")
    if not isinstance(raw_entries, list):
        raise YamlMetadataPatchError("YAML 元数据事务缺少文件清单")
    project = Path(project_dir).resolve()
    roots = {identifier: Path(root).absolute() for identifier, root in (repository_roots or {None: project}).items()}
    originals: dict[Path, bytes] = {}
    prepared: list[tuple[Path, bytes, bytes]] = []
    seen_targets: set[str] = set()
    for index, raw_entry in enumerate(raw_entries):
        if not isinstance(raw_entry, Mapping):
            raise YamlMetadataPatchError(
                f"YAML 元数据事务 entries[{index}] 必须是对象"
            )
        relative_path = raw_entry.get("path")
        if not isinstance(relative_path, str):
            raise YamlMetadataPatchError(
                "YAML 元数据事务文件路径重复或无效",
                code="yaml_transaction_path_duplicate",
            )
        identifier = raw_entry.get("repository_id")
        if identifier not in roots or str(roots[identifier].resolve()) != raw_entry.get("root_path"):
            raise YamlMetadataPatchError("YAML 事务恢复绑定与原目标仓库位置不一致", code="yaml_transaction_repository_changed")
        root = roots[identifier]
        target = _transaction_target(root, relative_path)
        target_identity = os.path.normcase(str(target))
        if target_identity in seen_targets:
            raise YamlMetadataPatchError(
                "YAML 元数据事务文件路径重复或无效",
                code="yaml_transaction_path_duplicate",
            )
        seen_targets.add(target_identity)
        try:
            current = target.read_bytes()
        except OSError as error:
            raise YamlMetadataPatchError(
                f"无法读取 YAML 事务文件：{relative_path}"
            ) from error
        current_sha256 = hashlib.sha256(current).hexdigest()
        before_sha256 = str(raw_entry.get("before_sha256") or "")
        after_sha256 = str(raw_entry.get("after_sha256") or "")
        if current_sha256 == after_sha256:
            continue
        if current_sha256 != before_sha256:
            raise YamlMetadataPatchError(
                f"YAML 元数据事务文件在恢复期间发生未授权变化：{relative_path}"
            )
        raw_replacements = raw_entry.get("replacements")
        if not isinstance(raw_replacements, list):
            raise YamlMetadataPatchError("YAML 元数据事务替换清单无效")
        replacements: dict[tuple[str | int, ...], Any] = {}
        for raw_replacement in raw_replacements:
            if (
                not isinstance(raw_replacement, Mapping)
                or not isinstance(raw_replacement.get("path"), list)
                or not raw_replacement["path"]
                or any(
                    not isinstance(part, (str, int)) or isinstance(part, bool)
                    for part in raw_replacement["path"]
                )
            ):
                raise YamlMetadataPatchError("YAML 元数据事务替换路径无效")
            metadata_path = tuple(raw_replacement["path"])
            if metadata_path in replacements:
                raise YamlMetadataPatchError("YAML 元数据事务替换路径重复")
            replacements[metadata_path] = raw_replacement.get("value")
        updated = render_yaml_value_patches(current, replacements)
        if hashlib.sha256(updated).hexdigest() != after_sha256:
            raise YamlMetadataPatchError(
                f"YAML 元数据事务目标散列无法重现：{relative_path}"
            )
        prepared.append((target, current, updated))
    try:
        for target, original, updated in prepared:
            originals[target] = original
            atomic_write_bytes(target, updated)
    except Exception as error:
        rollback_failures: list[str] = []
        for target, original in reversed(list(originals.items())):
            try:
                atomic_write_bytes(target, original)
            except Exception:
                rollback_failures.append(target.as_posix())
        if rollback_failures:
            raise YamlMetadataPatchError(
                "YAML 元数据事务写入失败且回滚不完整："
                + "、".join(rollback_failures),
                code="yaml_transaction_rollback_incomplete",
                details={"paths": rollback_failures},
            ) from error
        raise YamlMetadataPatchError(
            "YAML 元数据事务写入失败，已恢复本次已写文件",
            code="yaml_transaction_write_failed_rolled_back",
        ) from error
    return originals


def restore_yaml_patch_originals(project_dir: str | Path, transaction: Mapping[str, Any], originals: Mapping[Path, bytes]) -> None:
    """Restore only this transaction's bytes; preserve intervening user edits."""
    entries = {}
    for entry in transaction.get("entries", []):
        root = Path(entry.get("root_path") or project_dir)
        entries[_transaction_target(root, entry["path"])] = entry
    for target, content in reversed(list(originals.items())):
        entry = entries.get(target)
        if entry is None or hashlib.sha256(content).hexdigest() != entry.get("before_sha256"):
            raise YamlMetadataPatchError("回滚内容不属于原事务", code="yaml_transaction_rollback_invalid")
        current = hashlib.sha256(target.read_bytes()).hexdigest()
        if current == entry["before_sha256"]:
            continue
        if current != entry["after_sha256"]:
            raise YamlMetadataPatchError("事务后文件已被其他操作修改，保留现场以便恢复", code="yaml_transaction_rollback_conflict")
        atomic_write_bytes(target, content)

