    def resolve_commit(self, ref: str) -> str:
        selected = str(ref or "").strip()
        if (
            _SAFE_REF.fullmatch(selected) is None
            or ".." in selected
            or selected.endswith("/")
            or "//" in selected
            or selected.startswith("-")
        ):
            raise GitProjectReaderError(
                "observed_ref 不是安全的本地 Git 引用",
                code="git_ref_invalid",
            )
        if _COMMIT.fullmatch(selected) and selected in self._verified_commits:
            return selected
        result = self._run(
            ["rev-parse", "--verify", f"{selected}^{{commit}}"],
            allow_failure=True,
        )
        commit = result.stdout_text().strip()
        if result.exit_code != 0 or _COMMIT.fullmatch(commit) is None:
            raise GitProjectReaderError(
                f"Git 引用不存在或不是提交：{selected}",
                code="git_ref_not_found",
            )
        self._verified_commits.add(commit)
        return commit

    def path_exists_at(self, commit: str, relative_path: str) -> bool:
        return relative_path in self._tree_entries_at(commit)

    def read_file_at(self, commit: str, relative_path: str) -> bytes:
        return self.read_files_at(commit, [relative_path])[relative_path]

    def read_files_at(
        self,
        commit: str,
        relative_paths: Sequence[str],
    ) -> dict[str, bytes]:
        """Read exact blob objects in bounded one-shot batches."""

        paths = list(dict.fromkeys(relative_paths))
        if not paths:
            return {}
        tree = self._tree_entries_at(commit)
        path_to_object: dict[str, str] = {}
        object_sizes: dict[str, int] = {}
        for path in paths:
            entry = tree.get(path)
            if entry is None:
                raise GitProjectReaderError(
                    f"{path} 在 Git 提交 {commit} 中不存在"
                )
            object_id, size, object_type, mode = entry
            if object_type != "blob" or size is None or mode not in {"100644", "100755"}:
                raise GitProjectReaderError(
                    f"{path} 在 Git 提交 {commit} 中不是普通文件",
                    code="git_entry_mode_unsupported",
                )
            if size + _BATCH_HEADER_ALLOWANCE > _MAX_GIT_OUTPUT_BYTES:
                raise GitProjectReaderError(
                    f"{path} 超过不可变项目文件读取上限"
                )
            path_to_object[path] = object_id
            object_sizes[object_id] = size

        pending = [
            object_id for object_id in object_sizes if object_id not in self._objects
        ]
        self._load_objects(pending, object_sizes)
        return {
            path: self._objects[object_id]
            for path, object_id in path_to_object.items()
        }

    def _load_objects(
        self,
        pending: Sequence[str],
        object_sizes: Mapping[str, int],
    ) -> None:
        """Share bounded immutable-object reads across tree and index views."""

        chunk: list[str] = []
        chunk_output_size = 0
        chunk_input_size = 0
        for object_id in pending:
            expected_output = object_sizes[object_id] + _BATCH_HEADER_ALLOWANCE
            expected_input = len(object_id) + 1
            if chunk and (
                chunk_output_size + expected_output > _MAX_GIT_OUTPUT_BYTES
                or chunk_input_size + expected_input > _MAX_GIT_INPUT_BYTES
            ):
                self._read_object_batch(chunk, object_sizes)
                chunk = []
                chunk_output_size = 0
                chunk_input_size = 0
            chunk.append(object_id)
            chunk_output_size += expected_output
            chunk_input_size += expected_input
        if chunk:
            self._read_object_batch(chunk, object_sizes)

    def tracked_paths_at(
        self,
        commit: str,
        *,
        prefix: str | None = None,
    ) -> list[str]:
        paths = self._tree_entries_at(commit)
        if prefix is None:
            return sorted(paths)
        boundary = prefix.rstrip("/") + "/"
        return sorted(
            path
            for path in paths
            if path == prefix or path.startswith(boundary)
        )

    def worktree_paths(self, *, prefix: str | None = None) -> list[str]:
        """List tracked and non-ignored untracked files through Git path rules."""

        arguments = [
            "-c",
            "core.quotepath=false",
            "ls-files",
            "--cached",
            "--others",
            "--exclude-standard",
            "-z",
            "--",
        ]
        if prefix is not None:
            arguments.append(f":(literal){prefix}")
        result = self._run(arguments)
        paths: list[str] = []
        for raw_path in result.stdout.split(b"\0"):
            if not raw_path:
                continue
            path = repository_path_from_git(raw_path, "Git 工作树路径")
            candidate = self.project.joinpath(*PurePosixPath(path).parts)
            if not candidate.is_file():
                continue
            paths.append(path)
            if len(paths) > _MAX_WORKTREE_PATHS:
                raise GitProjectReaderError(
                    "Git 工作树文件数量超过实现观察上限",
                    code="worktree_path_limit_exceeded",
                    details={"limit": _MAX_WORKTREE_PATHS},
                )
        return sorted(set(paths))

    def _tree_entries_at(
        self,
        commit: str,
    ) -> dict[str, tuple[str, int | None, str, str]]:
        cached = self._trees.get(commit)
        if cached is not None:
            return cached
        result = self._run(
            [
                "-c",
                "core.quotepath=false",
                "ls-tree",
                "-r",
                "--long",
                "-z",
                commit,
                "--",
            ]
        )
        entries: dict[str, tuple[str, int | None, str, str]] = {}
        for record in result.stdout.split(b"\0"):
            if not record:
                continue
            header, separator, raw_path = record.partition(b"\t")
            parts = header.split()
            if not separator or len(parts) != 4:
                raise GitProjectReaderError("Git 树快照格式无效")
            raw_mode, raw_type, raw_object_id, raw_size = parts
            try:
                mode = raw_mode.decode("ascii", errors="strict")
                object_type = raw_type.decode("ascii", errors="strict")
                object_id = raw_object_id.decode("ascii", errors="strict")
                path = repository_path_from_git(raw_path, "Git 树路径")
                size = None if raw_size == b"-" else int(raw_size)
            except GitProjectReaderError:
                raise
            except (UnicodeError, ValueError) as error:
                raise GitProjectReaderError("Git 树快照内容无效") from error
            if _OBJECT_ID.fullmatch(object_id) is None or path in entries:
                raise GitProjectReaderError("Git 树快照对象或路径无效")
            if mode not in {"100644", "100755", "120000", "160000"}:
                raise GitProjectReaderError("Git 树快照文件模式无效")
            entries[path] = (object_id, size, object_type, mode)
        self._trees[commit] = entries
        return entries

    def _read_object_batch(
        self,
        object_ids: Sequence[str],
        expected_sizes: Mapping[str, int],
    ) -> None:
        stdin_bytes = b"".join(
            object_id.encode("ascii") + b"\n" for object_id in object_ids
        )
        loaded: dict[str, bytes] = {}
        try:
            result = self._run(
                ["cat-file", "--batch"],
                stdin_bytes=stdin_bytes,
            )
            cursor = 0
            for expected_object_id in object_ids:
                header_end = result.stdout.find(b"\n", cursor)
                if header_end < 0:
                    raise GitProjectReaderError("Git 批量对象输出缺少头部")
                header = result.stdout[cursor:header_end].split()
                if len(header) != 3:
                    raise GitProjectReaderError("Git 批量对象输出头部无效")
                try:
                    object_id = header[0].decode("ascii", errors="strict")
                    object_type = header[1].decode("ascii", errors="strict")
                    size = int(header[2])
                except (UnicodeError, ValueError) as error:
                    raise GitProjectReaderError(
                        "Git 批量对象输出头部无效"
                    ) from error
                if (
                    object_id != expected_object_id
                    or object_type != "blob"
                    or size != expected_sizes[expected_object_id]
                ):
                    raise GitProjectReaderError(
                        "Git 批量对象输出与树快照不一致"
                    )
                content_start = header_end + 1
                content_end = content_start + size
                if (
                    content_end >= len(result.stdout)
                    or result.stdout[content_end : content_end + 1] != b"\n"
                ):
                    raise GitProjectReaderError("Git 批量对象输出长度无效")
                loaded[object_id] = result.stdout[content_start:content_end]
                cursor = content_end + 1
            if cursor != len(result.stdout):
                raise GitProjectReaderError("Git 批量对象输出包含多余内容")
        except GitProjectReaderError:
            loaded = {}
            for object_id in object_ids:
                fallback = self._run(["cat-file", "blob", object_id])
                if len(fallback.stdout) != expected_sizes[object_id]:
                    raise GitProjectReaderError(
                        "Git 单对象回退读取与树快照长度不一致"
                    )
                loaded[object_id] = fallback.stdout
        self._objects.update(loaded)

    def changed_paths_between(
        self,
        older_commit: str,
        newer_commit: str,
    ) -> list[str]:
        result = self._run(
            [
                "-c",
                "core.quotepath=false",
                "diff",
                "--name-only",
                "-z",
                older_commit,
                newer_commit,
                "--",
            ]
        )
        try:
            return sorted(
                repository_path_from_git(value, "Git 变化路径")
                for value in result.stdout.split(b"\0")
                if value
            )
        except UnicodeError as error:
            raise GitProjectReaderError("Git 路径必须是 UTF-8") from error

    def change_entries(
        self, older_commit: str, newer_commit: str | None,
    ) -> list[dict[str, str | None]]:
        """Read changes, retaining both rename endpoints without executing filters."""

        if newer_commit is None:
            # Even a name-only diff can invoke a clean/process filter while
            # comparing worktree bytes. Reject conversions before asking Git
            # for any diff, using the same policy as canonical content reads.
            paths = self.worktree_paths()
            for path, attributes in self._explicit_path_attributes_many(paths).items():
                self._validate_conversion_attributes(path, attributes)
        arguments = [
            # Porcelain diff can refresh stat-only index entries even when
            # optional locks are disabled. A query must preserve index bytes.
            "-c", "core.quotepath=false", "-c", "diff.autoRefreshIndex=false",
            "diff", "--no-ext-diff",
            "--no-textconv", "--name-status", "-z", "--find-renames", older_commit,
        ]
        if newer_commit is not None:
            arguments.append(newer_commit)
        tokens = self._run([*arguments, "--"]).stdout.split(b"\0")
        entries: list[dict[str, str | None]] = []
        index = 0
        while index < len(tokens) and tokens[index]:
            status = tokens[index].decode("ascii", errors="strict")
            count = 2 if status.startswith(("R", "C")) else 1
            if index + count >= len(tokens) or any(not item for item in tokens[index + 1:index + count + 1]):
                raise GitProjectReaderError("Git 变化记录不完整", code="git_change_output_invalid")
            paths = [repository_path_from_git(item, "Git 变化路径") for item in tokens[index + 1:index + count + 1]]
            entries.append({
                "status": status,
                "old_path": paths[0] if status[0] != "A" else None,
                "path": paths[-1] if status[0] != "D" else None,
            })
            index += count + 1
        if newer_commit is None:
            # Name-only output can retain stat-only entries when automatic
            # index refresh is disabled. Numstat actually compares contents;
            # retain its real changes, including zero-line mode changes.
            if entries:
                raw_changes = self._run([
                    *("--numstat" if value == "--name-status" else value
                      for value in arguments), "--",
                ]).stdout.split(b"\0")
                changed_paths: set[str] = set()
                position = 0
                while position < len(raw_changes) and raw_changes[position]:
                    fields = raw_changes[position].split(b"\t", 2)
                    if len(fields) != 3 or any(
                        count != b"-" and not count.isdigit() for count in fields[:2]
                    ):
                        raise GitProjectReaderError("Git 变化统计格式无效", code="git_change_output_invalid")
                    position += 1
                    paths = [fields[2]]
                    if not fields[2]:
                        paths = raw_changes[position:position + 2]
                        if len(paths) != 2 or any(not path for path in paths):
                            raise GitProjectReaderError("Git 重命名统计不完整", code="git_change_output_invalid")
                        position += 2
                    changed_paths.update(repository_path_from_git(path, "Git 变化统计路径") for path in paths)
                entries = [entry for entry in entries if entry["path"] in changed_paths or entry["old_path"] in changed_paths]
            raw = self._run(["ls-files", "--others", "--exclude-standard", "-z"]).stdout
            entries.extend({
                "status": "?", "old_path": None,
                "path": repository_path_from_git(path, "Git 未跟踪路径"),
            } for path in raw.split(b"\0") if path)
        return sorted(entries, key=lambda item: (item["path"] or item["old_path"] or "", item["status"] or ""))

    def is_ancestor(self, older_commit: str, newer_commit: str) -> bool:
        """Return whether the older commit is an ancestor of the newer one."""

        result = self._run(
            ["merge-base", "--is-ancestor", older_commit, newer_commit],
            allow_failure=True,
        )
        if result.exit_code == 0:
            return True
        if result.exit_code == 1:
            return False
        raise GitProjectReaderError(
            "无法判断 Git 提交祖先关系："
            f"{older_commit} -> {newer_commit}"
        )

    def pending_operations(self) -> list[str]:
        result = self._run(["rev-parse", "--absolute-git-dir"])
        try:
            directory = Path(result.stdout.decode("utf-8").rstrip("\r\n"))
            if not directory.is_absolute() or not directory.is_dir():
                raise ValueError
            return [name for name in ("MERGE_HEAD", "CHERRY_PICK_HEAD", "REVERT_HEAD", "rebase-merge", "rebase-apply", "sequencer") if (directory / name).exists()]
        except (OSError, UnicodeError, ValueError) as error:
            raise GitProjectReaderError("无法确定工作树实际 Git 操作状态", code="git_operation_state_invalid") from error

    def worktree_dirty(self) -> bool:
        result = self._run(
            ["-c", "core.quotepath=false", "status", "--porcelain", "-z"]
        )
        return bool(result.stdout)

    def canonical_worktree_bytes(
        self,
        relative_path: str,
        content: bytes,
        *,
        explicit_attributes: Mapping[str, str] | None = None,
        index_blobs: Mapping[str, bytes | None] | None = None,
        autocrlf: str | None = None,
    ) -> bytes:
        """Return the bytes Git would store for one working-tree file."""

        if len(content) > _MAX_GIT_INPUT_BYTES:
            raise GitProjectReaderError(
                f"{relative_path} 超过工作树规范内容读取上限"
            )
        if explicit_attributes is None:
            explicit_attributes = self._explicit_path_attributes(relative_path)
        self._validate_conversion_attributes(relative_path, explicit_attributes)
        text_attribute = explicit_attributes.get("text", "unspecified")
        if text_attribute not in {"set", "unset", "auto", "unspecified"}:
            raise GitProjectReaderError(
                f"当前文件使用了不能安全重放的 text 属性：{relative_path}"
            )
        eol_attribute = explicit_attributes.get("eol", "unspecified")
        if eol_attribute not in {"lf", "crlf", "unspecified"}:
            raise GitProjectReaderError(
                f"当前文件使用了不能安全重放的 eol 属性：{relative_path}"
            )
        crlf_attribute = explicit_attributes.get("crlf", "unspecified")
        if crlf_attribute not in {"set", "unset", "input", "unspecified"}:
            raise GitProjectReaderError(
                f"当前文件使用了不能安全重放的 crlf 属性：{relative_path}"
            )
        if crlf_attribute != "unspecified":
            if text_attribute != "unspecified" or eol_attribute != "unspecified":
                raise GitProjectReaderError(
                    f"当前文件同时使用了新旧换行属性，不能安全重放：{relative_path}"
                )
            if crlf_attribute == "set":
                text_attribute = "set"
            elif crlf_attribute == "unset":
                text_attribute = "unset"
            else:
                text_attribute = "set"
                eol_attribute = "lf"

        binary = _git_auto_text_is_binary(content)
        normalize_text = False
        if text_attribute == "set":
            normalize_text = True
        elif text_attribute == "auto":
            indexed = (
                self._index_blob_bytes(relative_path)
                if index_blobs is None
                else index_blobs[relative_path]
            )
            normalize_text = not binary and not _index_preserves_crlf(indexed)
        elif text_attribute == "unspecified":
            if autocrlf is None:
                autocrlf = self._core_autocrlf()
            indexed = (
                self._index_blob_bytes(relative_path)
                if index_blobs is None
                else index_blobs[relative_path]
            )
            normalize_text = (
                autocrlf in {"true", "input"}
                and not binary
                and not _index_preserves_crlf(indexed)
            )
        if eol_attribute in {"lf", "crlf"} and text_attribute == "unspecified":
            normalize_text = True
        return content.replace(b"\r\n", b"\n") if normalize_text else content

    @staticmethod
    def _validate_conversion_attributes(
        relative_path: str,
        explicit_attributes: Mapping[str, str],
    ) -> None:
        unsafe_attributes = {
            name: value
            for name, value in explicit_attributes.items()
            if name in {"filter", "ident", "working-tree-encoding"}
        }
        if unsafe_attributes:
            detail = "、".join(
                f"{name}={value}"
                for name, value in sorted(unsafe_attributes.items())
            )
            raise GitProjectReaderError(
                "当前文件配置了Strixnova不会执行的 Git 提交转换："
                f"{relative_path}（{detail}）；"
                "请先移除外部 clean filter（提交前转换器）、ident "
                "（对象身份展开）或 working-tree-encoding（工作树编码转换）",
                code="git_conversion_unsafe",
                details={"path": relative_path, "attributes": unsafe_attributes},
            )
    def _core_autocrlf(self) -> str:
        raw = self._run(
            ["config", "--get", "core.autocrlf"], allow_failure=True
        ).stdout_text().strip().casefold()
        if raw == "input":
            return "input"
        if not raw:
            return "false"
        parsed = self._run(
            ["config", "--type=bool", "--get", "core.autocrlf"],
            allow_failure=True,
        )
        value = parsed.stdout_text().strip().casefold()
        if parsed.exit_code != 0 or value not in {"false", "true"}:
            raise GitProjectReaderError(
                "core.autocrlf 使用了不能安全解释的值：" + raw
            )
        return value

    @staticmethod
    def _path_chunks(paths: Sequence[str]) -> Iterator[list[str]]:
        chunk: list[str] = []
        size = 0
        limit = min(16 * 1024, _MAX_GIT_INPUT_BYTES)
        for path in paths:
            cost = len(path.encode("utf-8")) + len(":(literal)") + 3
            if cost > limit:
                raise GitProjectReaderError("仓库路径超过批读取上限")
            if chunk and (size + cost > limit or len(chunk) >= 128):
                yield chunk
                chunk, size = [], 0
            chunk.append(path)
            size += cost
        if chunk:
            yield chunk

    def canonical_worktree_files(
        self, contents: Mapping[str, bytes]
    ) -> dict[str, bytes]:
        """Use invocation-local metadata; never cache mutable path state."""

        if not contents:
            return {}
        for path, content in contents.items():
            if len(content) > _MAX_GIT_INPUT_BYTES:
                raise GitProjectReaderError(
                    f"{path} 超过工作树规范内容读取上限"
                )
        attributes = self._explicit_path_attributes_many(list(contents))
        for path, selected in attributes.items():
            self._validate_conversion_attributes(path, selected)
        index_paths = [
            path for path, selected in attributes.items()
            if selected.get("text", "unspecified") in {"auto", "unspecified"}
            and selected.get("crlf", "unspecified") == "unspecified"
        ]
        index_blobs = self._index_blobs_many(index_paths)
        autocrlf = (
            self._core_autocrlf()
            if any(
                attributes[path].get("text", "unspecified") == "unspecified"
                for path in index_paths
            )
            else None
        )
        return {
            path: self.canonical_worktree_bytes(
                path, content,
                explicit_attributes=attributes[path],
                index_blobs=index_blobs,
                autocrlf=autocrlf,
            )
            for path, content in contents.items()
        }

    def _index_blobs_many(
        self, relative_paths: Sequence[str]
    ) -> dict[str, bytes | None]:
        paths = list(dict.fromkeys(relative_paths))
        selected: dict[str, str] = {}
        for chunk in self._path_chunks(paths):
            result = self._run(
                ["ls-files", "--stage", "-z", "--",
                 *(f":(literal){path}" for path in chunk)],
                allow_failure=True,
            )
            if result.exit_code != 0:
                return {path: self._index_blob_bytes(path) for path in paths}
            requested = set(chunk)
            for record in result.stdout.split(b"\0"):
                if not record:
                    continue
                header, separator, raw_path = record.partition(b"\t")
                parts = header.split()
                if not separator or len(parts) != 3:
                    raise GitProjectReaderError("Git 暂存区条目格式无效")
                try:
                    mode, object_id, stage = (
                        value.decode("ascii", errors="strict") for value in parts
                    )
                    path = repository_path_from_git(raw_path, "Git 暂存区路径")
                except UnicodeError as error:
                    raise GitProjectReaderError("Git 暂存区条目编码无效") from error
                if (
                    path not in requested or path in selected
                    or mode not in {"100644", "100755"} or stage != "0"
                    or _OBJECT_ID.fullmatch(object_id) is None
                ):
                    raise GitProjectReaderError(
                        f"Git 暂存区条目身份无效：{path}"
                    )
                selected[path] = object_id
        pending = [
            oid for oid in dict.fromkeys(selected.values())
            if oid not in self._objects
        ]
        sizes: dict[str, int] = {}
        for chunk in self._path_chunks(pending):
            result = self._run(
                ["cat-file", "--batch-check"],
                stdin_bytes=("\n".join(chunk) + "\n").encode("ascii"),
            )
            lines = result.stdout.splitlines()
            if len(lines) != len(chunk):
                raise GitProjectReaderError("Git 暂存区对象信息不完整")
            for expected, line in zip(chunk, lines, strict=True):
                fields = line.split()
                if len(fields) != 3 or fields[0] != expected.encode("ascii"):
                    raise GitProjectReaderError("Git 暂存区对象身份无效")
                try:
                    size = int(fields[2])
                except ValueError as error:
                    raise GitProjectReaderError("Git 暂存区对象大小无效") from error
                if fields[1] != b"blob" or not 0 <= size <= _MAX_GIT_INPUT_BYTES:
                    raise GitProjectReaderError("Git 暂存区对象类型或大小无效")
                sizes[expected] = size
        self._load_objects(pending, sizes)
        if any(
            len(self._objects[object_id]) > _MAX_GIT_INPUT_BYTES
            for object_id in selected.values()
        ):
            raise GitProjectReaderError("Git 暂存区对象超过工作树规范内容读取上限")
        return {
            path: self._objects[selected[path]] if path in selected else None
            for path in paths
        }

    def _explicit_path_attributes_many(
        self, relative_paths: Sequence[str]
    ) -> dict[str, dict[str, str]]:
        attributes: dict[str, dict[str, str]] = {
            path: {} for path in relative_paths
        }
        for chunk in self._path_chunks(relative_paths):
            result = self._run(
                ["check-attr", "-z", "--all", "--stdin"],
                stdin_bytes=("\0".join(chunk) + "\0").encode("utf-8"),
            )
            fields = result.stdout.split(b"\0")
            if fields and fields[-1] == b"":
                fields.pop()
            if len(fields) % 3:
                raise GitProjectReaderError("Git 显式路径属性响应不完整")
            requested = set(chunk)
            try:
                for index in range(0, len(fields), 3):
                    path = repository_path_from_git(fields[index], "Git 属性路径")
                    name = fields[index + 1].decode("utf-8", errors="strict")
                    value = fields[index + 2].decode("utf-8", errors="strict")
                    if path not in requested or name in attributes[path]:
                        raise GitProjectReaderError("Git 显式路径属性身份无效")
                    attributes[path][name] = value
            except UnicodeError as error:
                raise GitProjectReaderError("Git 路径属性不是有效 UTF-8") from error
        return attributes

    def _index_blob_bytes(self, relative_path: str) -> bytes | None:
        result = self._run(
            ["ls-files", "--stage", "-z", "--", relative_path],
            allow_failure=True,
        )
        if result.exit_code != 0 or not result.stdout:
            return None
        records = [record for record in result.stdout.split(b"\0") if record]
        if len(records) != 1:
            raise GitProjectReaderError(
                f"Git 暂存区包含不能安全解释的多阶段条目：{relative_path}"
            )
        header, separator, raw_path = records[0].partition(b"\t")
        parts = header.split()
        if not separator or len(parts) != 3:
            raise GitProjectReaderError(
                f"Git 暂存区条目格式无效：{relative_path}"
            )
        raw_mode, raw_object_id, raw_stage = parts
        try:
            mode = raw_mode.decode("ascii", errors="strict")
            object_id = raw_object_id.decode("ascii", errors="strict")
            stage = raw_stage.decode("ascii", errors="strict")
            path = repository_path_from_git(raw_path, "Git 暂存区路径")
        except UnicodeError as error:
            raise GitProjectReaderError(
                f"Git 暂存区条目编码无效：{relative_path}"
            ) from error
        if (
            mode not in {"100644", "100755"}
            or _OBJECT_ID.fullmatch(object_id) is None
            or stage != "0"
            or path != relative_path
        ):
            raise GitProjectReaderError(
                f"Git 暂存区条目身份无效：{relative_path}"
            )
        blob = self._objects.get(object_id)
        if blob is None:
            blob = self._run(["cat-file", "blob", object_id]).stdout
        if len(blob) > _MAX_GIT_INPUT_BYTES:
            raise GitProjectReaderError(
                f"{relative_path} 超过工作树规范内容读取上限"
            )
        self._objects[object_id] = blob
        return blob

    def _explicit_path_attributes(self, relative_path: str) -> dict[str, str]:
        """Return only attributes explicitly selected for one path.

        ``git check-attr <name>`` renders an absent attribute and a literal
        value such as ``filter=unspecified`` with the same text.  ``--all``
        omits truly absent attributes, so an attacker cannot hide a configured
        clean driver behind one of Git's presentation words.  Any explicit
        conversion attribute is rejected conservatively, including an explicit
        unset declaration, because safety matters more than accepting a
        redundant attribute spelling.
        """

        result = self._run(["check-attr", "-z", "--all", "--", relative_path])
        fields = result.stdout.split(b"\0")
        if fields and fields[-1] == b"":
            fields.pop()
        if len(fields) % 3:
            raise GitProjectReaderError(
                f"Git 没有返回完整的显式路径属性：{relative_path}"
            )
        attributes: dict[str, str] = {}
        try:
            for index in range(0, len(fields), 3):
                path = repository_path_from_git(
                    fields[index],
                    "Git 显式路径属性路径",
                )
                name = fields[index + 1].decode("utf-8", errors="strict")
                value = fields[index + 2].decode("utf-8", errors="strict")
                if path != relative_path:
                    raise GitProjectReaderError(
                        f"Git 显式路径属性身份不匹配：{relative_path}"
                    )
                attributes[name] = value
        except UnicodeError as error:
            raise GitProjectReaderError(
                f"Git 显式路径属性不是有效 UTF-8：{relative_path}"
            ) from error
        return attributes

    def _run(
        self,
        arguments: list[str],
        *,
        allow_failure: bool = False,
        stdin_bytes: bytes | None = None,
    ) -> ProcessResult:
        environment = dict(os.environ)
        for name in (
            "GIT_DIR",
            "GIT_WORK_TREE",
            "GIT_COMMON_DIR",
            "GIT_INDEX_FILE",
            "GIT_OBJECT_DIRECTORY",
            "GIT_ALTERNATE_OBJECT_DIRECTORIES",
            "GIT_PREFIX",
            "GIT_CONFIG_PARAMETERS",
        ):
            environment.pop(name, None)
        environment.update(
            {
                "GIT_CONFIG_COUNT": "2",
                "GIT_CONFIG_KEY_0": "safe.directory",
                "GIT_CONFIG_VALUE_0": self.project.as_posix(),
                "GIT_CONFIG_KEY_1": "core.fsmonitor",
                "GIT_CONFIG_VALUE_1": "false",
                "GIT_NO_REPLACE_OBJECTS": "1",
                "GIT_NO_LAZY_FETCH": "1",
                "GIT_OPTIONAL_LOCKS": "0",
                "GIT_TERMINAL_PROMPT": "0",
            }
        )
        try:
            command = [str(self.git), *arguments]
            result = run_process(
                command,
                cwd=self.project,
                policy=ProcessPolicy.exact(
                    "strixnova.git-project-reader.v1",
                    "read_project_git_state",
                    command,
                ),
                env=environment,
                limits=ProcessLimits(
                    timeout_seconds=60,
                    cleanup_timeout_seconds=10,
                    max_input_bytes=_MAX_GIT_INPUT_BYTES,
                    max_output_bytes=_MAX_GIT_OUTPUT_BYTES,
                ),
                stdin_bytes=stdin_bytes,
            )
        except ProcessExecutionError as error:
            raise GitProjectReaderError(str(error)) from error
        if result.exit_code != 0 and not allow_failure:
            raise GitProjectReaderError(
                "只读 Git 命令失败："
                + " ".join(arguments)
                + (f"：{result.stderr_text().strip()}" if result.stderr else "")
            )
        return result


def repository_relative_path(value: Any, field: str = "path") -> str:
    """Validate and normalize one ordinary repository-relative path."""

    if not isinstance(value, str) or not value.strip():
        raise GitProjectReaderError(
            f"{field} 必须是非空字符串",
            code="repository_path_invalid",
        )
    raw = value.strip()
    if "\\" in raw:
        raise GitProjectReaderError(
            f"{field} 必须使用仓库规范的 / 路径分隔符",
            code="repository_path_invalid",
        )
    path = PurePosixPath(raw)
    if (
        path.is_absolute()
        or ".." in path.parts
        or ":" in raw
        or not path.parts
        or path.parts[0].casefold() in FORBIDDEN_PROJECT_ROOTS
        or path.as_posix() != raw
    ):
        raise GitProjectReaderError(
            f"{field} 必须是仓库内普通相对路径",
            code="repository_path_invalid",
        )
    return path.as_posix()


def repository_scope_root(value: Any, field: str = "root") -> str:
    """Allow the repository itself as a source scope, never as a file path."""

    if value == ".":
        return "."
    return repository_relative_path(value, field)


class GitProjectReader:
    """Small shared boundary for ref-aware long-lived project authorities."""

    def __init__(
        self,
        project_dir: str | Path,
        *,
        observed_ref: str | None = None,
    ) -> None:
        self.project = Path(project_dir).expanduser().resolve()
        if not self.project.is_dir():
            raise GitProjectReaderError(f"项目目录不存在：{self.project}")
        self.observed_commit: str | None = None
        self._git: _ReadOnlyGit | None = None
        self._exists_cache: dict[str, bool] = {}
        self._bytes_cache: dict[str, bytes] = {}
        self._repository_scope: RepositoryReadScope | None = None
        if observed_ref is not None:
            self._git = _ReadOnlyGit(self.project)
            self.observed_commit = self._git.resolve_commit(observed_ref)

    def repository_scope(self, repository_id: str) -> RepositoryReadScope:
        """Inspect only local Git metadata; never derive the declared identity."""

        if not isinstance(repository_id, str) or re.fullmatch(
            r"REPO-[0-9A-F]{16}", repository_id
        ) is None:
            raise GitProjectReaderError(
                "仓库身份必须匹配 REPO-加十六位大写十六进制",
                code="repository_identity_invalid",
            )
        git = self._git or _ReadOnlyGit(self.project)
        self._git = git
        raw = git._run(["rev-parse", "--git-common-dir"]).stdout_text().strip()
        if not raw:
            raise GitProjectReaderError(
                "无法确定仓库共同目录", code="git_common_directory_invalid"
            )
        common = Path(raw)
        if not common.is_absolute():
            common = self.project / common
        common = common.resolve()
        if not common.is_dir():
            raise GitProjectReaderError(
                "仓库共同目录不可用", code="git_common_directory_invalid"
            )
        return RepositoryReadScope(repository_id, self.project, common)

    def bind_repository_identity(self, repository_id: str) -> RepositoryReadScope:
        """Bind a newly read declaration to this already selected reader."""

        self._repository_scope = self.repository_scope(repository_id)
        return self._repository_scope

    @property
    def repository_id(self) -> str | None:
        return self._repository_scope.repository_id if self._repository_scope is not None else None

    @classmethod
    def for_repository(
        cls,
        scope: RepositoryReadScope,
        *,
        observed_ref: str | None = None,
    ) -> GitProjectReader:
        """Bind an immutable scope, rechecking its root before content reads."""

        if not isinstance(scope, RepositoryReadScope):
            raise GitProjectReaderError(
                "读取必须提供已解析仓库范围", code="repository_scope_required"
            )
        reader = cls(scope.project_dir, observed_ref=observed_ref)
        return reader.bind_repository(scope)

    def bind_repository(self, scope: RepositoryReadScope) -> GitProjectReader:
        """Attach a checked identity while retaining this reader's exact cache."""

        if not isinstance(scope, RepositoryReadScope):
            raise GitProjectReaderError("读取必须提供已解析仓库范围", code="repository_scope_required")
        current = self.repository_scope(scope.repository_id)
        if current != scope:
            raise GitProjectReaderError(
                "仓库本机绑定已经改变",
                code="repository_binding_changed",
                details={"repository_id": scope.repository_id},
            )
        self._repository_scope = current
        return self

    def content_window(
        self,
        relative_path: str,
        *,
        offset: int = 0,
        limit: int = 65536,
        expected_sha256: str | None = None,
    ) -> dict[str, Any]:
        """Return exact canonical bytes in a bounded, digest-bound window."""

        if self._repository_scope is None:
            raise GitProjectReaderError(
                "内容窗口必须绑定明确仓库身份", code="repository_scope_required"
            )
        if (
            isinstance(offset, bool) or not isinstance(offset, int) or offset < 0
            or isinstance(limit, bool) or not isinstance(limit, int)
            or not 1 <= limit <= 1048576
        ):
            raise GitProjectReaderError(
                "字节位置或窗口长度无效", code="repository_content_range_invalid"
            )
        if expected_sha256 is not None and (
            not isinstance(expected_sha256, str)
            or re.fullmatch(r"[0-9a-f]{64}", expected_sha256) is None
        ):
            raise GitProjectReaderError(
                "预期内容摘要无效", code="repository_content_digest_invalid"
            )
        path = repository_relative_path(relative_path, "reference.path")
        if self.observed_commit is None:
            parent = self.project
            for part in PurePosixPath(path).parts[:-1]:
                parent = parent / part
                if parent.is_symlink() or parent.is_junction():
                    raise GitProjectReaderError(
                        "仓库内容路径不得经过链接", code="repository_symlink_forbidden"
                    )
                if (parent / ".git").exists():
                    raise GitProjectReaderError(
                        "内容路径进入了另一个仓库工作区",
                        code="repository_content_crosses_worktree",
                        details={"path": path},
                    )
        content = self.read_canonical_bytes(path, "仓库内容")
        digest = hashlib.sha256(content).hexdigest()
        if expected_sha256 is not None and digest != expected_sha256:
            raise GitProjectReaderError(
                "仓库内容已经改变",
                code="repository_content_changed",
                details={"expected_sha256": expected_sha256, "actual_sha256": digest},
            )
        if offset > len(content):
            raise GitProjectReaderError(
                "字节位置超出文件长度", code="repository_content_range_invalid"
            )
        chunk = content[offset:offset + limit]
        next_offset = offset + len(chunk) if offset + len(chunk) < len(content) else None
        return {
            "schema_version": "strixnova.repository-content.v1",
            "repository_id": self._repository_scope.repository_id,
            "path": path,
            "scope": "git_commit" if self.observed_commit is not None else "working_tree",
            "observed_commit": self.observed_commit,
            "byte_representation": "git_canonical",
            "sha256": digest,
            "size_bytes": len(content),
            "offset": offset,
            "returned_bytes": len(chunk),
            "encoding": "base64",
            "content_base64": base64.b64encode(chunk).decode("ascii"),
            "next_offset": next_offset,
            "writes_performed": False,
        }

    def absolute_path(self, relative_path: str) -> Path:
        normalized = repository_relative_path(relative_path)
        candidate = self.project
        for part in PurePosixPath(normalized).parts:
            candidate = candidate / part
            if candidate.is_symlink() or candidate.is_junction():
                raise GitProjectReaderError(
                    f"项目工作树规范读取不接受符号链接：{normalized}",
                    code="repository_symlink_forbidden",
                )
            if (self._repository_scope is not None and candidate != self.project / normalized
                    and (candidate / ".git").exists()):
                raise GitProjectReaderError(
                    "内容路径进入了另一个仓库工作区", code="repository_content_crosses_worktree",
                )
        try:
            resolved = candidate.resolve()
            resolved.relative_to(self.project)
        except (OSError, RuntimeError, ValueError) as error:
            raise GitProjectReaderError(
                f"项目工作树路径不得通过链接指向仓库外：{normalized}",
                code="repository_symlink_forbidden",
            ) from error
        return resolved

    def exists(self, relative_path: str) -> bool:
        normalized = repository_relative_path(relative_path)
        if self.observed_commit is None:
            return self.absolute_path(normalized).is_file()
        if normalized in self._exists_cache:
            return self._exists_cache[normalized]
        assert self._git is not None
        exists = self._git.path_exists_at(self.observed_commit, normalized)
        self._exists_cache[normalized] = exists
        return exists

    def path_scope_exists(self, relative_path: str) -> bool:
        """Accept an ordinary file or directory/prefix at the selected ref."""

        normalized = repository_scope_root(relative_path)
        if normalized == ".":
            return self.project.is_dir()
        if self.observed_commit is None:
            return self.absolute_path(normalized).exists()
        assert self._git is not None
        if self._git.path_exists_at(self.observed_commit, normalized):
            return True
        return bool(
            self._git.tracked_paths_at(
                self.observed_commit,
                prefix=normalized,
            )
        )

    def read_bytes(self, relative_path: str, label: str = "项目文件") -> bytes:
        normalized = repository_relative_path(relative_path)
        if self.observed_commit is None:
            try:
                return self.absolute_path(normalized).read_bytes()
            except OSError as error:
                raise GitProjectReaderError(
                    f"无法读取 {label}：{normalized}"
                ) from error
        if normalized in self._bytes_cache:
            return self._bytes_cache[normalized]
        assert self._git is not None
        try:
            self.prefetch([normalized])
            return self._bytes_cache[normalized]
        except GitProjectReaderError as error:
            raise GitProjectReaderError(
                f"无法从 Git 读取 {label}：{normalized}",
                code=error.code,
                details=error.details,
            ) from error

    def read_canonical_bytes(
        self,
        relative_path: str,
        label: str = "项目文件",
    ) -> bytes:
        """Read bytes in the same canonical form used by a future Git blob."""

        normalized = repository_relative_path(relative_path)
        content = self.read_bytes(normalized, label)
        if self.observed_commit is not None:
            return content
        git = self._git or _ReadOnlyGit(self.project)
        self._git = git
        return git.canonical_worktree_bytes(normalized, content)

    def prefetch(self, relative_paths: Sequence[str]) -> None:
        """Batch immutable file reads into this command-scoped reader."""

        normalized = [
            repository_relative_path(path)
            for path in dict.fromkeys(relative_paths)
        ]
        if self.observed_commit is None or not normalized:
            return
        pending = [
            path for path in normalized if path not in self._bytes_cache
        ]
        if not pending:
            return
        assert self._git is not None
        loaded = self._git.read_files_at(self.observed_commit, pending)
        self._bytes_cache.update(loaded)
        self._exists_cache.update({path: True for path in loaded})

    def iter_canonical_files(
        self,
        relative_paths: Sequence[str],
        label: str = "项目文件",
    ) -> Iterator[tuple[str, bytes]]:
        """Yield bounded fresh worktree batches, or the exact immutable view.

        Path attributes, configuration and index selection live only within a
        batch. Subsequent calls on this reader must observe their current state.
        Only immutable Git object contents are reused across calls.
        """

        if isinstance(relative_paths, (str, bytes)):
            raise GitProjectReaderError("批读取路径必须是路径集合")
        paths = list(dict.fromkeys(
            repository_relative_path(path) for path in relative_paths
        ))
        if not paths:
            return
        if self.observed_commit is not None:
            self.prefetch(paths)
            for path in paths:
                yield path, self.read_canonical_bytes(path, label)
            return
        git = self._git or _ReadOnlyGit(self.project)
        self._git = git
        for chunk in git._path_chunks(paths):
            contents: dict[str, bytes] = {}
            size = 0
            for path in chunk:
                content = self.read_bytes(path, label)
                if len(content) > _MAX_GIT_INPUT_BYTES:
                    raise GitProjectReaderError(
                        f"{path} 超过工作树规范内容读取上限"
                    )
                if contents and size + len(content) > _MAX_GIT_OUTPUT_BYTES:
                    yield from git.canonical_worktree_files(contents).items()
                    contents, size = {}, 0
                contents[path] = content
                size += len(content)
            if contents:
                yield from git.canonical_worktree_files(contents).items()

    def changed_paths_between(self, newer_ref: str) -> list[str]:
        """Return paths changed from the selected immutable commit to another ref."""

        if self.observed_commit is None or self._git is None:
            raise GitProjectReaderError("变化比较必须从精确 Git 提交读取")
        newer_commit = self._git.resolve_commit(newer_ref)
        return self._git.changed_paths_between(
            self.observed_commit,
            newer_commit,
        )

    def changes_from(self, base_ref: str) -> dict[str, Any]:
        """Compare a fixed base with this reader's commit or current worktree."""

        if self._git is None:
            self._git = _ReadOnlyGit(self.project)
        base_commit = self._git.resolve_commit(base_ref)
        return {
            "repository_id": self.repository_id,
            "base_commit": base_commit,
            "target_commit": self.observed_commit,
            "scope": "git_commit" if self.observed_commit is not None else "working_tree",
            "entries": self._git.change_entries(base_commit, self.observed_commit),
        }

    def resolve_commit(self, ref: str = "HEAD") -> str:
        """Resolve a selected ref without invoking the local-delivery module."""

        git = self._git or _ReadOnlyGit(self.project)
        return git.resolve_commit(ref)

    def is_ancestor(self, older_ref: str, newer_ref: str) -> bool:
        """Compare two immutable refs through the read-only Git boundary."""

        git = self._git or _ReadOnlyGit(self.project)
        older_commit = (
            older_ref
            if _COMMIT.fullmatch(str(older_ref))
            else git.resolve_commit(older_ref)
        )
        newer_commit = (
            newer_ref
            if _COMMIT.fullmatch(str(newer_ref))
            else git.resolve_commit(newer_ref)
        )
        return git.is_ancestor(older_commit, newer_commit)

    def pending_operations(self) -> list[str]:
        """Read this worktree's actual Git metadata, including linked trees."""
        git = self._git or _ReadOnlyGit(self.project)
        return git.pending_operations()

    def worktree_dirty(self) -> bool:
        """Return the native Git worktree state without persisting a shadow."""

        git = self._git or _ReadOnlyGit(self.project)
        return git.worktree_dirty()

    def tracked_paths(self, prefix: str | None = None) -> list[str]:
        """List project files at the selected commit or current working tree."""

        normalized_prefix = (
            repository_relative_path(prefix, "prefix")
            if prefix is not None and prefix != "."
            else None
        )
        if self.observed_commit is not None:
            assert self._git is not None
            return self._git.tracked_paths_at(
                self.observed_commit,
                prefix=normalized_prefix,
            )
        if self._git is None:
            try:
                self._git = _ReadOnlyGit(self.project)
            except GitProjectReaderError as error:
                marker = self.project / ".git"
                # An explicitly selected, unbound directory may live inside
                # another repository. Its working files remain local inputs;
                # the ancestor's identity and ignore rules are not its basis.
                # Exact-ref and bound-repository readers still require their
                # own verified Git root and never take this fallback.
                directory_only = (
                    error.code == "git_repository_mismatch"
                    and self._repository_scope is None
                    and not marker.exists()
                    and not marker.is_symlink()
                )
                if error.code not in {
                    "git_not_available",
                    "git_repository_required",
                } and not directory_only:
                    raise
        if self._git is not None:
            return self._git.worktree_paths(prefix=normalized_prefix)
        root = (
            self.absolute_path(normalized_prefix)
            if normalized_prefix is not None
            else self.project
        )
        if root.is_file():
            return [root.relative_to(self.project).as_posix()]
        if not root.exists():
            return []
        paths: list[str] = []
        for path in root.rglob("*"):
            if not path.is_file() or "__pycache__" in path.parts:
                continue
            paths.append(path.relative_to(self.project).as_posix())
            if len(paths) > _MAX_WORKTREE_PATHS:
                raise GitProjectReaderError(
                    "非 Git 项目文件数量超过实现观察上限",
                    code="worktree_path_limit_exceeded",
                    details={"limit": _MAX_WORKTREE_PATHS},
                )
        return sorted(paths)

    def read_text(self, relative_path: str, label: str = "项目文件") -> str:
        normalized = repository_relative_path(relative_path)
        try:
            return self.read_bytes(normalized, label).decode("utf-8")
        except UnicodeError as error:
            raise GitProjectReaderError(
                f"{label} 必须是 UTF-8：{normalized}"
            ) from error

    def load_yaml(self, relative_path: str, label: str = "项目文件") -> Any:
        normalized = repository_relative_path(relative_path)
        try:
            return yaml.safe_load(self.read_text(normalized, label))
        except yaml.YAMLError as error:
            raise GitProjectReaderError(
                f"{label} YAML 无效：{normalized}"
            ) from error

def verification_snapshot_matches(
    expected: Mapping[str, Any], current: Mapping[str, Any],
    continued_paths: Mapping[str | None, set[str]],
) -> bool:
    if not continued_paths:
        return expected == current

    def retained(value):
        repositories = []
        for entry in value.get('repositories') or []:
            if entry.get('content_sha256') != content_fingerprint(entry.get('paths')):
                return None
            remaining = [path for path in entry['paths'] if path['path'] not in continued_paths.get(entry['repository_id'], set())]
            repositories.append({**entry, 'paths': remaining, 'content_sha256': content_fingerprint(remaining)})
        original = {'repositories': value.get('repositories'), 'dependencies': value.get('dependencies')}
        if value.get('content_sha256') != content_fingerprint(original):
            return None
        selected = {**value, 'repositories': repositories}
        selected['content_sha256'] = content_fingerprint({'repositories': repositories, 'dependencies': value.get('dependencies')})
        return selected

    retained_expected, retained_current = retained(expected), retained(current)
    return retained_expected is not None and retained_expected == retained_current


def verification_input_paths(plan: Mapping[str, Any], command: Mapping[str, Any], repository_id: str | None, reader: GitProjectReader) -> set[str]:
    """Bind a command to its declared inputs and preceding slice dependencies.

    A later slice's exclusive paths are not inputs to an earlier slice unless
    its case report explicitly declares them. Other existing files remain
    conservative inputs when no case-level input list is available.
    """
    declared = (command.get("case_report") or {}).get("input_paths")
    if declared and repository_id == command.get("repository_id"):
        paths: set[str] = set()
        for path in declared:
            children = reader.tracked_paths(path)
            paths.update(children or [path])
        return paths
    slices = {value["slice_id"]: value for value in plan.get("implementation_slices") or []}
    included = {identifier for identifier, value in slices.items() if command.get("command_id") in value.get("verification_command_ids", [])}
    pending = list(included)
    while pending:
        for dependency in slices[pending.pop()].get("depends_on", []):
            if dependency not in included:
                included.add(dependency)
                pending.append(dependency)
    owned = {reference for identifier in included for field in ("operation_refs", "continued_operation_refs") for reference in slices[identifier].get(field, [])}
    planned, relevant = set(), set()
    for index, operation in enumerate(plan.get("operations") or []):
        if operation.get("repository_id") != repository_id:
            continue
        paths = {str(path) for path in (operation.get("path"), operation.get("to_path")) if path}
        planned.update(paths)
        if not included or f"operations[{index}]" in owned:
            relevant.update(paths)
    return (set(reader.tracked_paths()) | relevant) - (planned - relevant)


def capture_repository_content(repository_id: str | None, reader: GitProjectReader, paths: Sequence[str] | None = None, *, canonical: bool = True) -> dict[str, Any]:
    selected = sorted(set(reader.tracked_paths() if paths is None else paths))
    selected = [path for path in selected if path.split("/", 1)[0] not in {".git", ".strixnova"}]
    existing = [path for path in selected if reader.exists(path)]
    contents = dict(reader.iter_canonical_files(existing, "project content input")) if canonical else {path: reader.read_bytes(path, "project content input") for path in existing}
    entries = []
    for path in selected:
        exists = path in contents
        entries.append({
            "path": path, "state": "file" if exists else "absent",
            "sha256": hashlib.sha256(contents[path]).hexdigest() if exists else "",
        })
    return {
        "repository_id": repository_id, "paths": entries,
        "content_sha256": content_fingerprint(entries),
    }


def compose_content_snapshot(plan_id: str, repositories: Sequence[Mapping[str, Any]], *, dependencies: Sequence[Mapping[str, Any]] = ()) -> dict[str, Any]:
    inputs = {"repositories": list(repositories), "dependencies": list(dependencies)}
    identifiers = [entry["repository_id"] for entry in repositories]
    if len(identifiers) != len(set(identifiers)):
        raise ValueError("A content snapshot cannot contain duplicate repository identities")
    return {
        "schema_version": "strixnova.project-content-snapshot.v1", "plan_id": plan_id,
        **inputs, "content_sha256": content_fingerprint(inputs),
        "semantic_content_machine_proven": False,
    }

def schema_error_message(error: Any) -> str:
    """Turn common JSON Schema failures into concise actionable Chinese."""

    if error.validator == "required" and isinstance(error.instance, Mapping):
        missing = sorted(set(error.validator_value) - set(error.instance))
        if missing:
            return "缺少必填字段：" + ", ".join(missing)
    if error.validator == "additionalProperties" and isinstance(
        error.instance,
        Mapping,
    ):
        allowed = set((error.schema.get("properties") or {}).keys())
        unexpected = sorted(set(error.instance) - allowed)
        if unexpected:
            return "包含不允许字段：" + ", ".join(unexpected)
    if error.validator == "enum":
        return (
            f"值 {error.instance!r} 不在允许集合中："
            + ", ".join(repr(item) for item in error.validator_value)
        )
    if error.validator == "const":
        return f"值必须是 {error.validator_value!r}"
    if error.validator == "type":
        expected = error.validator_value
        if isinstance(expected, list):
            expected_text = "、".join(
                _TYPE_NAMES.get(str(item), str(item)) for item in expected
            )
        else:
            expected_text = _TYPE_NAMES.get(str(expected), str(expected))
        return f"值类型必须是{expected_text}"
    if error.validator == "format":
        selected = str(error.validator_value)
        return f"值必须符合{_FORMAT_NAMES.get(selected, selected)}格式"
    if error.validator == "pattern":
        return f"值不符合格式 {error.validator_value}"
    if error.validator == "minItems":
        return f"至少需要 {error.validator_value} 项"
    if error.validator == "maxItems":
        return f"最多允许 {error.validator_value} 项"
    if error.validator == "minProperties":
        return f"对象至少需要 {error.validator_value} 个字段"
    if error.validator == "maxProperties":
        return f"对象最多允许 {error.validator_value} 个字段"
    if error.validator == "minLength":
        return f"文本长度至少为 {error.validator_value}"
    if error.validator == "maxLength":
        return f"文本长度最多为 {error.validator_value}"
    if error.validator == "minimum":
        return f"数值不得小于 {error.validator_value}"
    if error.validator == "maximum":
        return f"数值不得大于 {error.validator_value}"
    if error.validator == "exclusiveMinimum":
        return f"数值必须大于 {error.validator_value}"
    if error.validator == "exclusiveMaximum":
        return f"数值必须小于 {error.validator_value}"
    if error.validator == "uniqueItems":
        return "列表内容不得重复"
    if error.validator == "oneOf":
        return "值不符合任何一个允许的结构分支"
    if error.validator == "anyOf":
        return "值不符合任一允许条件"
    if error.validator == "not":
        return "值命中了明确禁止的结构"
    return f"值不符合结构规则：{error.validator}"

def input_snapshot(root: Path, paths: Sequence[str]) -> dict[str, Any]:
    files = []
    total = 0
    for relative in sorted(paths):
        path = ordinary_path(root, relative_path(relative))
        if not path.is_file():
            _fail(f"声明的受测输入不存在：{relative}", "test_case_input_missing")
        before = path.stat()
        size = before.st_size
        total += size
        if size > 64 * 1024 * 1024 or total > 256 * 1024 * 1024:
            _fail("声明的受测输入超过有界快照限制")
        with path.open("rb") as source:
            sha = hashlib.file_digest(source, "sha256").hexdigest()
        after = path.stat()
        if after.st_size != size or after.st_mtime_ns != before.st_mtime_ns:
            _fail("受测输入在快照期间改变", "test_case_inputs_changed")
        files.append({"path": relative, "sha256": sha, "size_bytes": size})
    return {"files": files, "sha256": digest(files), "scope": "declared_inputs_only"}


def snapshot_matches(root: Path, snapshot: Mapping[str, Any], *, exclude_paths: Sequence[str] = ()) -> bool:
    try:
        if exclude_paths:
            if snapshot.get('sha256') != digest(snapshot['files']):
                return False
            retained = [item for item in snapshot['files'] if item['path'] not in exclude_paths]
            snapshot = {**snapshot, 'files': retained, 'sha256': digest(retained)}
        return input_snapshot(root, [item["path"] for item in snapshot["files"]]) == snapshot
    except (OSError, KeyError, TypeError, TestCaseEvidenceError):
        return False


def receipts_with_freshness(receipts: Sequence[Mapping[str, Any]], root: Path | None, *, exclude_paths: Sequence[str] = ()) -> list[dict[str, Any]]:
    """Annotate a disposable projection; never rewrite the recorded Agent assessment."""
    result = deepcopy(list(receipts))
    if root is not None:
        for receipt in result:
            evidence = receipt.get("case_evidence")
            if isinstance(evidence, Mapping):
                receipt["_case_input_stale"] = evidence.get("status") == "inputs_changed" or not snapshot_matches(root, evidence.get("input_snapshot", {}), exclude_paths=exclude_paths)
    return result


def adapter_path() -> Path:
    return Path(__file__).parent / "resources" / "case-adapters" / "strixnova_builtin_pytest_cases.py"


def adapter_environment(report_path: Path, run_id: str) -> tuple[dict[str, str], str]:
    path = adapter_path()
    sha = hashlib.sha256(path.read_bytes()).hexdigest()
    env = dict(os.environ)
    env["STRIXNOVA_CASE_REPORT_PATH"] = str(report_path)
    env["STRIXNOVA_CASE_RUN_ID"] = run_id
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    env["PYTHONPATH"] = str(path.parent) + (os.pathsep + env["PYTHONPATH"] if env.get("PYTHONPATH") else "")
    plugins = [value for value in env.get("PYTEST_PLUGINS", "").split(",") if value]
    env["PYTEST_PLUGINS"] = ",".join(dict.fromkeys([*plugins, path.stem]))
    return env, sha


def report_results(report: Any, *, config: Mapping[str, Any], run_id: str, adapter_sha256: str, execution_root: Path) -> list[dict[str, Any]]:
    fields = {"schema_version", "run_id", "adapter", "adapter_sha256", "framework_version", "python_version", "test_root", "collection_complete", "session_finished", "exit_status", "collected_test_ids", "deselected_test_ids", "collection_errors", "results"}
    if not isinstance(report, Mapping) or set(report) != fields or report.get("schema_version") != REPORT_SCHEMA:
        _fail("用例报告结构无效", "test_case_report_invalid")
    if report["run_id"] != run_id or report["adapter"] != config["adapter"] or report["adapter_sha256"] != adapter_sha256:
        _fail("用例报告不属于本次真实执行或当前适配器", "test_case_report_mismatch")
    declared_root = ordinary_path(execution_root, config["test_root"]).resolve()
    reported_root = _text(report["test_root"], "report.test_root")
    if not Path(reported_root).is_absolute() or os.path.normcase(os.path.normpath(reported_root)) != os.path.normcase(str(declared_root)):
        _fail("用例报告测试根与方案不同", "test_case_report_mismatch")
    _text(report["framework_version"], "framework_version")
    _text(report["python_version"], "python_version")
    if report["collection_complete"] is not True or report["session_finished"] is not True or type(report["exit_status"]) is not int:
        _fail("用例收集或执行未完整结束", "test_case_report_incomplete")
    for field in ("collected_test_ids", "deselected_test_ids", "collection_errors", "results"):
        if not isinstance(report[field], list) or len(report[field]) > 100000:
            _fail(f"用例报告 {field} 无效")
    if any(not isinstance(item, str) for item in report["collection_errors"]):
        _fail("收集错误必须使用明确文本")
    collected = report["collected_test_ids"]
    deselected = report["deselected_test_ids"]
    if any(not isinstance(item, str) or not item for item in [*collected, *deselected]) or len(set(collected)) != len(collected) or set(collected) & set(deselected):
        _fail("用例收集身份重复、无效或状态冲突")
    phases: dict[str, dict[str, Mapping[str, Any]]] = {}
    for row in report["results"]:
        if not isinstance(row, Mapping) or set(row) != {"test_id", "phase", "outcome", "expected_failure"}:
            _fail("用例阶段结果结构无效")
        identifier, phase, outcome = row["test_id"], row["phase"], row["outcome"]
        if not isinstance(identifier, str) or identifier not in collected or not isinstance(phase, str) or phase not in {"setup", "call", "teardown"} or not isinstance(outcome, str) or outcome not in {"passed", "failed", "skipped"} or type(row["expected_failure"]) is not bool:
            _fail("用例阶段结果不属于实际收集或使用未知状态")
        if phase in phases.setdefault(identifier, {}):
            _fail("同一用例阶段存在多个结果，不能用重试覆盖失败")
        phases[identifier][phase] = row

    def status(identifier: str) -> str:
        if identifier in deselected:
            return "deselected"
        if identifier not in collected:
            return "not_collected"
        found = phases.get(identifier, {})
        if any(item["outcome"] == "failed" for key, item in found.items() if key != "call"):
            return "error"
        if any(item["expected_failure"] for item in found.values()):
            return "xpassed" if found.get("call", {}).get("outcome") == "passed" else "xfailed"
        if any(item["outcome"] == "failed" for item in found.values()):
            return "failed"
        if any(item["outcome"] == "skipped" for item in found.values()):
            return "skipped"
        if set(found) != {"setup", "call", "teardown"}:
            return "not_run"
        return "passed"

    result = []
    for binding in config["bindings"]:
        tests = [{"test_id": identifier, "status": status(identifier)} for identifier in binding["test_ids"]]
        passed = not report["collection_errors"] and all(test["status"] == "passed" for test in tests)
        result.append({"example_ref": binding["example_ref"], "example_sha256": config["example_fingerprints"][binding["example_ref"]], "status": "passed" if passed else "with_gaps", "tests": tests})
    return result


def unexecuted_examples(config: Mapping[str, Any]) -> list[dict[str, Any]]:
    return [{
        "example_ref": binding["example_ref"],
        "example_sha256": config["example_fingerprints"][binding["example_ref"]],
        "status": "with_gaps",
        "tests": [{"test_id": identifier, "status": "not_run"} for identifier in binding["test_ids"]],
    } for binding in config["bindings"]]


class CaseExecution:
    """One report owned by one supervised command; no persistent workflow state."""

    def __init__(self, config: Mapping[str, Any], *, execution_root: Path, artifact_root: Path, work_item_id: str, receipt_id: str, plan_id: str) -> None:
        self.config = normalize_config(config, bound=True)
        self.execution_root = execution_root
        self.snapshot = input_snapshot(execution_root, self.config["input_paths"])
        safe_item = "".join(c if c.isalnum() or c in "._-" else "-" for c in work_item_id).strip("-")
        relative = f"{safe_item}/{receipt_id}.cases.json"
        self.report_path = ordinary_path(artifact_root, relative)
        self.report_path.parent.mkdir(parents=True, exist_ok=True)
        if self.report_path.exists():
            _fail("本次用例报告位置已经存在，拒绝复用旧报告")
        self.receipt_id, self.plan_id = receipt_id, plan_id
        self.env, self.adapter_sha256 = adapter_environment(self.report_path, receipt_id)

    def finish(self, *, exit_code: int | None) -> dict[str, Any]:
        result = {
            "schema_version": EVIDENCE_SCHEMA,
            "run_id": self.receipt_id,
            "plan_id": self.plan_id,
            "adapter": self.config["adapter"],
            "adapter_sha256": self.adapter_sha256,
            "binding_sha256": digest(self.config),
            "input_snapshot": self.snapshot,
            "status": "report_missing",
            "report_ref": str(self.report_path),
            "report_sha256": None,
            "report_size_bytes": None,
            "example_results": unexecuted_examples(self.config),
            "limitations": [],
        }
        try:
            if self.report_path.is_symlink() or self.report_path.is_junction():
                _fail("用例报告不能是链接", "test_case_path_invalid")
            if not self.report_path.is_file():
                _fail("本次命令没有生成逐用例报告", "test_case_report_missing")
            with self.report_path.open("rb") as source:
                payload = source.read(MAX_REPORT_BYTES + 1)
            if len(payload) > MAX_REPORT_BYTES:
                _fail("用例报告超过大小限制", "test_case_report_invalid")
            result["report_sha256"] = hashlib.sha256(payload).hexdigest()
            result["report_size_bytes"] = len(payload)
            report = json.loads(payload)
            if not isinstance(report, Mapping) or report.get("exit_status") != exit_code:
                _fail("报告退出状态与实际进程结果不同", "test_case_report_mismatch")
            result["example_results"] = report_results(
                report, config=self.config, run_id=self.receipt_id,
                adapter_sha256=self.adapter_sha256, execution_root=self.execution_root,
            )
            result["status"] = "recorded"
        except (OSError, ValueError, TypeError) as error:
            result["status"] = "report_missing" if isinstance(error, TestCaseEvidenceError) and error.code == "test_case_report_missing" else "report_invalid"
            result["limitations"].append(str(error))
        if not snapshot_matches(self.execution_root, self.snapshot):
            result["status"] = "inputs_changed"
            result["limitations"].append("声明的受测输入在执行期间改变；本回执不能证明当前输入。")
        return result


def validate_evidence(value: Any, config: Mapping[str, Any], *, receipt_id: str) -> dict[str, Any]:
    fields = {"schema_version", "run_id", "plan_id", "adapter", "adapter_sha256", "binding_sha256", "input_snapshot", "status", "report_ref", "report_sha256", "report_size_bytes", "example_results", "limitations"}
    if not isinstance(value, Mapping) or set(value) != fields or value.get("schema_version") != EVIDENCE_SCHEMA:
        _fail("逐用例回执结构无效")
    if value["run_id"] != receipt_id or value["binding_sha256"] != digest(config) or value["adapter"] != config["adapter"]:
        _fail("逐用例回执与本次命令或例子关联不一致")
    _text(value["plan_id"], "case_evidence.plan_id")
    _text(value["report_ref"], "case_evidence.report_ref")
    if not isinstance(value["adapter_sha256"], str) or not _SHA.fullmatch(value["adapter_sha256"]):
        _fail("报告适配器身份无效")
    if not isinstance(value["limitations"], list) or any(not isinstance(item, str) or not item.strip() for item in value["limitations"]):
        _fail("报告限制必须是明确文本数组")
    if not isinstance(value["status"], str) or value["status"] not in {"recorded", "report_missing", "report_invalid", "inputs_changed"}:
        _fail("逐用例证据状态无效")
    snapshot = value["input_snapshot"]
    if not isinstance(snapshot, Mapping) or set(snapshot) != {"files", "sha256", "scope"} or snapshot.get("scope") != "declared_inputs_only" or not isinstance(snapshot["files"], list):
        _fail("受测输入快照结构无效")
    paths = []
    for item in snapshot["files"]:
        if not isinstance(item, Mapping) or set(item) != {"path", "sha256", "size_bytes"} or not isinstance(item["sha256"], str) or not _SHA.fullmatch(item["sha256"]) or type(item["size_bytes"]) is not int or item["size_bytes"] < 0:
            _fail("受测输入文件记录无效")
        paths.append(item["path"])
    if paths != config["input_paths"] or snapshot["sha256"] != digest(snapshot["files"]):
        _fail("受测输入快照不匹配声明范围")
    results = value["example_results"]
    if not isinstance(results, list) or len(results) != len(config["bindings"]):
        _fail("逐例结果不完整")
    for row, binding in zip(results, config["bindings"], strict=True):
        if not isinstance(row, Mapping) or set(row) != {"example_ref", "example_sha256", "status", "tests"} or row["example_ref"] != binding["example_ref"] or row["example_sha256"] != config["example_fingerprints"][binding["example_ref"]]:
            _fail("逐例结果身份或版本无效")
        tests = row["tests"]
        if not isinstance(tests, list) or len(tests) != len(binding["test_ids"]):
            _fail("逐例测试结果不完整")
        for test, identifier in zip(tests, binding["test_ids"], strict=True):
            if not isinstance(test, Mapping) or set(test) != {"test_id", "status"} or test["test_id"] != identifier or not isinstance(test["status"], str) or test["status"] not in {"passed", "failed", "error", "skipped", "xfailed", "xpassed", "deselected", "not_collected", "not_run"}:
                _fail("测试结果身份或状态无效")
        if not isinstance(row["status"], str) or row["status"] not in {"passed", "with_gaps"} or (row["status"] == "passed" and not all(test["status"] == "passed" for test in tests)):
            _fail("逐例通过声明与实际测试状态矛盾")
    if value["status"] == "recorded" and (not isinstance(value["report_sha256"], str) or not _SHA.fullmatch(value["report_sha256"]) or type(value["report_size_bytes"]) is not int):
        _fail("已记录报告缺少实际文件指纹")
    return deepcopy(dict(value))

def collect_dependency_evidence(checks: Sequence[Mapping[str, Any]], stdout: bytes, *, observed_at: str) -> dict[str, Any]:
    reports: dict[str, tuple[dict[str, Any], int, str]] = {}
    malformed = []
    for index, line in enumerate(stdout.decode('utf-8', errors='replace').splitlines(), 1):
        if not line.startswith(MARKER):
            continue
        raw = line[len(MARKER):]
        try:
            if len(raw.encode('utf-8')) > 65536:
                raise ValueError
            value = json.loads(raw)
            required = {'schema_version', 'dependency_id', 'version', 'contract_sha256', 'environment', 'evidence_refs'}
            if not isinstance(value, dict) or set(value) != required or value['schema_version'] != 'strixnova.dependency-observation.v1':
                raise ValueError
            identifier = value['dependency_id']
            if not isinstance(identifier, str) or identifier in reports:
                raise ValueError
            if not isinstance(value['evidence_refs'], list) or not value['evidence_refs'] or any(not isinstance(ref, str) or not ref.strip() for ref in value['evidence_refs']):
                raise ValueError
            reports[identifier] = (value, index, hashlib.sha256(raw.encode('utf-8')).hexdigest())
        except (ValueError, TypeError, KeyError):
            malformed.append(index)
    records = []
    expected_ids = {entry['dependency_id'] for entry in checks}
    for check in checks:
        found = reports.get(check['dependency_id'])
        observation, line_number, digest = found if found is not None else (None, None, None)
        matches = observation is not None and all(observation.get(actual) == check[expected] for actual, expected in (('version', 'expected_version'), ('contract_sha256', 'expected_contract_sha256'), ('environment', 'environment')))
        records.append({
            'dependency_id': check['dependency_id'], 'kind': check['kind'],
            'status': 'matched' if matches else 'missing' if observation is None else 'mismatch',
            'observed_at': observed_at, 'max_age_seconds': check['max_age_seconds'],
            'observation': observation, 'stdout_line': line_number, 'report_sha256': digest,
        })
    return {
        'schema_version': 'strixnova.verification-dependency-evidence.v1',
        'status': 'complete' if not malformed and not (set(reports) - expected_ids) and all(entry['status'] == 'matched' for entry in records) else 'blocked',
        'records': records, 'malformed_stdout_lines': malformed,
        'unplanned_dependency_ids': sorted(set(reports) - expected_ids),
        'source_scope': 'observations_from_approved_command_stdout',
        'source_code_coverage_proven': False, 'semantic_content_machine_proven': False,
    }


def validate_dependency_evidence(evidence: Any, checks: Sequence[Mapping[str, Any]]) -> None:
    if not isinstance(evidence, Mapping) or evidence.get('schema_version') != 'strixnova.verification-dependency-evidence.v1' or evidence.get('semantic_content_machine_proven') is not False or evidence.get('source_code_coverage_proven') is not False:
        raise ValueError('Dependency evidence must preserve its observation and source-coverage boundary')
    records = evidence.get('records')
    if not isinstance(records, list) or len(records) != len(checks):
        raise ValueError('Dependency evidence must cover exactly the planned checks')
    matched = True
    for check, record in zip(checks, records, strict=True):
        if not isinstance(record, Mapping) or any(record.get(key) != check[key] for key in ('dependency_id', 'kind', 'max_age_seconds')):
            raise ValueError('Dependency evidence is bound to different requirements')
        observation = record.get('observation')
        matches = isinstance(observation, Mapping) and all(observation.get(actual) == check[expected] for actual, expected in (('version', 'expected_version'), ('contract_sha256', 'expected_contract_sha256'), ('environment', 'environment')))
        if record.get('status') != ('matched' if matches else 'missing' if observation is None else 'mismatch'):
            raise ValueError('Dependency evidence status does not follow its observed facts')
        matched = matched and matches
    complete = matched and not evidence.get('malformed_stdout_lines') and not evidence.get('unplanned_dependency_ids')
    if evidence.get('status') != ('complete' if complete else 'blocked'):
        raise ValueError('Dependency evidence summary contradicts its observations')


def dependency_evidence_stale(evidence: Mapping[str, Any], *, now: datetime | None = None) -> bool:
    if evidence.get('status') != 'complete':
        return False
    current = now or datetime.now(timezone.utc)
    for record in evidence.get('records', []):
        age = record.get('max_age_seconds')
        if age is None:
            continue
        try:
            observed = datetime.fromisoformat(str(record['observed_at']).replace('Z', '+00:00'))
            if observed.tzinfo is None or (current - observed).total_seconds() < 0 or (current - observed).total_seconds() > age:
                return True
        except (ValueError, KeyError, TypeError):
            return True
    return False
